502	  /**
503	   * #1855: install crash handlers for uncaught exceptions and unhandled
504	   * rejections. Without these, a thrown error from any timer callback,
505	   * worker logic path, or transitive import crashes the daemon process
506	   * silently — the PID file leaks and any in-flight child processes
507	   * orphan. With these, we log a structured crash record, run stop()
508	   * to clean up, then exit 1 so the process actually dies (otherwise
509	   * Node would crash anyway after the handler returns).
510	   */
511	  private installCrashHandlers(): void {
512	    const onCrash = (kind: 'uncaughtException' | 'unhandledRejection', err: unknown) => {
513	      // Best-effort logging; never throw from inside the crash handler.
514	      try {
515	        this.writeCrashRecord(kind, err);
516	      } catch { /* nothing more we can do */ }
517	      try {
518	        // Synchronous stop — don't await; the process is dying. Just
519	        // remove the PID file and snapshot state so the next start
520	        // sees a clean slate.
521	        this.removePidFile();
522	        this.saveState();
523	        // Snapshot any in-flight child PIDs one last time so the next
524	        // lifetime can reap them.
525	        this.writeChildrenSnapshot();
526	      } catch { /* ignore */ }
527	      // Exit non-zero so supervisors / shells see the failure.
528	      process.exit(1);
529	    };
530	    process.on('uncaughtException', (err) => onCrash('uncaughtException', err));
531	    process.on('unhandledRejection', (err) => onCrash('unhandledRejection', err));
532	  }
