536	   * Inspectable by hand or via `ruflo daemon status` follow-ups.
537	   */
538	  private writeCrashRecord(kind: string, err: unknown): void {
539	    const logDir = this.config.logDir;
540	    if (!existsSync(logDir)) mkdirSync(logDir, { recursive: true });
541	    const crashLog = join(logDir, 'crash.log');
542	    const ts = new Date().toISOString();
543	    const message = err instanceof Error ? err.message : String(err);
544	    const stack = err instanceof Error && err.stack ? err.stack : '<no stack>';
545	    const record = `[${ts}] [${kind}] pid=${process.pid} ${message}\n${stack}\n---\n`;
546	    appendFileSync(crashLog, record, 'utf-8');
