572	      const startedAt = state.lastStartedAt?.getTime() ?? 0;
573	      const lastRunAt = state.lastRun?.getTime() ?? 0;
574	      // started after the last successful completion → was mid-flight
575	      if (startedAt > 0 && startedAt > lastRunAt) {
576	        state.failureCount++;
577	        state.isRunning = false;
578	        // Don't bump runCount — it was already incremented at start
579	        this.log(
