27	/**
28	 * Binary Min Heap for O(log n) priority queue operations
29	 * Used for candidate selection in HNSW search
30	 */
31	class BinaryMinHeap<T> {
32	  private heap: Array<{ item: T; priority: number }> = [];
33	
34	  get size(): number {
35	    return this.heap.length;
36	  }
37	
38	  insert(item: T, priority: number): void {
39	    this.heap.push({ item, priority });
40	    this.bubbleUp(this.heap.length - 1);
41	  }
42	
43	  extractMin(): T | undefined {
44	    if (this.heap.length === 0) return undefined;
45	    const min = this.heap[0].item;
46	    const last = this.heap.pop()!;
47	    if (this.heap.length > 0) {
48	      this.heap[0] = last;
49	      this.bubbleDown(0);
50	    }
51	    return min;
52	  }
53	
54	  peek(): T | undefined {
55	    return this.heap[0]?.item;
56	  }
57	
58	  peekPriority(): number | undefined {
59	    return this.heap[0]?.priority;
60	  }
61	
62	  isEmpty(): boolean {
63	    return this.heap.length === 0;
64	  }
65	
66	  toArray(): T[] {
67	    return this.heap
68	      .slice()
69	      .sort((a, b) => a.priority - b.priority)
70	      .map((entry) => entry.item);
71	  }
72	
73	  private bubbleUp(index: number): void {
74	    while (index > 0) {
75	      const parent = Math.floor((index - 1) / 2);
76	      if (this.heap[parent].priority <= this.heap[index].priority) break;
77	      [this.heap[parent], this.heap[index]] = [this.heap[index], this.heap[parent]];
78	      index = parent;
79	    }
80	  }
81	
82	  private bubbleDown(index: number): void {
83	    const length = this.heap.length;
84	    while (true) {
85	      let smallest = index;
86	      const left = 2 * index + 1;
87	      const right = 2 * index + 2;
88	      if (left < length && this.heap[left].priority < this.heap[smallest].priority) {
89	        smallest = left;
90	      }
91	      if (right < length && this.heap[right].priority < this.heap[smallest].priority) {
92	        smallest = right;
93	      }
94	      if (smallest === index) break;
95	      [this.heap[smallest], this.heap[index]] = [this.heap[index], this.heap[smallest]];
96	      index = smallest;
97	    }
98	  }
99	}
